    for i in range(4):
        p=params.copy()
        step=0.05*abs(params[i]) if params[i]!=0 else 0.1
        if i==1:
            step=0.1*abs(params[i]) if params[i]!=0 else 1.0
        if i==3:
            step=0.05*abs(params[i]) if params[i]!=0 else 0.1
        p[i]+=step
        simplex.append(p)
    simplex=np.array(simplex)
    vals=np.array([sse(p) for p in simplex])
    alpha=1.0; gamma_nm=2.0; rho=0.5; sigma=0.5
