        simplex=simplex[order]; vals=vals[order]
        if np.std(vals) < 1e-6:
            break
        centroid=np.mean(simplex[:-1], axis=0)
        worst=simplex[-1]
        reflected=centroid + alpha*(centroid-worst)
        vr=sse(reflected)
        if vr < vals[0]:
            expanded=centroid + gamma_nm*(reflected-centroid)
            ve=sse(expanded)
            if ve < vr:
                simplex[-1]=expanded; vals[-1]=ve
            else:
