                simplex[-1]=contracted; vals[-1]=vc
            else:
                best=simplex[0]
                new=[best]
                for i in range(1,len(simplex)):
                    new.append(best + sigma*(simplex[i]-best))
                simplex=np.array(new)
                vals=np.array([sse(p) for p in simplex])
    best=simplex[0]
    return best

# choose ranges for peaks
ranges={
